<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {getPlatforms,followPlatform,unfollowPlatform} from '../api';import type {FederationPlatform} from '../types';import {RouterLink} from 'vue-router';import {Network,Users,FileText,Check,Plus,Minus,Search} from 'lucide-vue-next'
const platforms=ref<FederationPlatform[]>([]),q=ref(''),loading=ref(true)
async function load(){loading.value=true;platforms.value=await getPlatforms();loading.value=false}onMounted(load)
const filtered=computed(()=>platforms.value.filter(p=>[p.name,p.handle,p.description].join(' ').toLowerCase().includes(q.value.toLowerCase())))
async function toggle(p:FederationPlatform){p.isFollowing?await unfollowPlatform(p.id):await followPlatform(p.id);platforms.value=await getPlatforms()}
</script>
<template><div class="page"><div class="section-head"><div><div class="eyebrow">Rede federada</div><h2>Descubra plataformas</h2><p>Encontre fontes de REA, siga as que interessam e receba suas publicações no seu feed.</p></div><RouterLink class="btn secondary" to="/federation/following"><Users :size="16"/> Minhas plataformas</RouterLink></div><div class="federation-explainer"><div class="explainer-icon"><Network :size="22"/></div><div><strong>Federação como uma rede social</strong><p>Uma plataforma pode publicar um recurso e outras plataformas podem acompanhar suas publicações. Ao seguir uma plataforma, você passa a receber seus novos recursos no seu feed.</p></div></div><div class="search"><div class="search-input-wrap"><Search :size="17"/><input class="input" v-model="q" placeholder="Pesquisar plataformas…"></div></div><div v-if="loading" class="card">Carregando plataformas…</div><div v-else class="platform-grid"><article v-for="p in filtered" :key="p.id" class="card platform-card"><div class="platform-top"><div class="platform-logo">{{p.name.slice(0,1)}}</div><span class="online"><i/> {{p.status}}</span></div><RouterLink :to="`/federation/${p.id}`"><h3>{{p.name}}</h3></RouterLink><div class="handle">{{p.handle}}</div><p>{{p.description}}</p><div class="platform-stats"><span><FileText :size="14"/> {{p.resourcesCount}} recursos</span><span><Users :size="14"/> {{p.followersCount}} seguidores</span></div><button class="btn full" :class="p.isFollowing?'secondary':'primary'" @click="toggle(p)"><Check v-if="p.isFollowing" :size="16"/><Plus v-else :size="16"/> {{p.isFollowing?'Seguindo':'Seguir plataforma'}}</button></article></div></div></template>
